INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Broadcastadresse immer die letzte Adresse im Subnetz?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert die höchste Adresse"}, {"text": "Nein", "correct": false, "because": "Korrekte Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist die Broadcastadresse für 192.168.1.0/26?', 3, '[{"text": "192.168.1.63", "correct": true, "because": "Inkrement 64, 0-63"}, {"text": "192.168.1.64", "correct": false, "because": "Nächstes Subnetz"}, {"text": "192.168.1.62", "correct": false, "because": "Vorletzte Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Broadcastadresse hat alle Hostbits auf 1. b) Sie ist die erste Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist die Netzwerkadresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Broadcastadresse?', 4, '[{"text": "Hostbits", "correct": false, "because": "Alle auf 1 gesetzt"}, {"text": "Inkrement", "correct": false, "because": "Bestimmt Bereich"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 10.0.0.255 die Broadcastadresse für /24 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Letzte Adresse bei 10.0.0.0/24"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat 172.16.0.0/27?', 3, '[{"text": "172.16.0.31", "correct": true, "because": "Inkrement 32, 0-31"}, {"text": "172.16.0.32", "correct": false, "because": "Nächstes Subnetz"}, {"text": "172.16.0.30", "correct": false, "because": "Vorletzte Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die Broadcastadresse?', 5, '[{"text": "Alle Hostbits auf 1", "correct": true, "because": "Definiert Broadcast"}, {"text": "Letzte Adresse im Subnetz", "correct": true, "because": "Bereichsende"}, {"text": "Erste Adresse", "correct": false, "because": "Das ist Netzwerkadresse"}, {"text": "Zufällige Bits", "correct": false, "because": "Fixe Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 192.168.1.15 ist Broadcast für /28. b) Sie ist immer 255.255.255.255. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nur bei /32"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Broadcastadresse?', 4, '[{"text": "Inkrement", "correct": false, "because": "Bestimmt Bereich"}, {"text": "Netzwerkadresse", "correct": false, "because": "Startpunkt"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 10.0.1.255 Broadcast für 10.0.0.0/23?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 512, 0.0-1.255"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat 192.168.10.0/25?', 4, '[{"text": "192.168.10.127", "correct": true, "because": "Inkrement 128, 0-127"}, {"text": "192.168.10.128", "correct": false, "because": "Nächstes Subnetz"}, {"text": "192.168.10.126", "correct": false, "because": "Vorletzte Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Broadcastadresse bei /32 0.0.0.0 ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "/32 ist 255.255.255.255"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Broadcast-Berechnung?', 3, '[{"text": "Inkrement", "correct": true, "because": "Bestimmt Bereichsende"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 172.16.0.63 ist Broadcast für /26. b) Sie ist die niedrigste Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Netzwerkadresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen sind Broadcastadressen?', 5, '[{"text": "192.168.1.31 für /27", "correct": true, "because": "Inkrement 32"}, {"text": "10.0.0.255 für /24", "correct": true, "because": "Inkrement 256"}, {"text": "192.168.1.0 für /26", "correct": false, "because": "Netzwerkadresse"}, {"text": "172.16.0.1 für /30", "correct": false, "because": "Hostadresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Broadcastadresse unwichtig?', 3, '[{"text": "Hostbits", "correct": false, "because": "Alle auf 1"}, {"text": "Inkrement", "correct": false, "because": "Definiert Bereich"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 192.168.0.7 Broadcast für 192.168.0.0/29?', 3, '[{"text": "Ja", "correct": true, "because": "Inkrement 8, 0-7"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 172.16.1.255 Broadcast für /24 ist?', 2, '[{"text": "Ja", "correct": true, "because": "Letzte Adresse bei 172.16.1.0/24"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat 10.10.0.0/22?', 4, '[{"text": "10.10.3.255", "correct": true, "because": "Inkrement 1.024, 0.0-3.255"}, {"text": "10.10.4.0", "correct": false, "because": "Nächstes Subnetz"}, {"text": "10.10.3.254", "correct": false, "because": "Vorletzte Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske hat 192.168.1.127 als Broadcast?', 3, '[{"text": "/25", "correct": true, "because": "Inkrement 128, 1.0-1.127"}, {"text": "/26", "correct": false, "because": "Inkrement 64"}, {"text": "/24", "correct": false, "because": "Inkrement 256"}]');
